#!/usr/bin/env bun
/**
 * PromptId codegen (eng review D6) — the prompts directory IS the source of truth.
 *
 *   bun prompts/codegen.ts          regenerate core/prompt-ids.ts
 *   bun prompts/codegen.ts --check  exit 1 if the generated file is stale (CI gate)
 *
 * Emits a closed union of every prompt id, so a graph referencing an unknown prompt — or
 * pasting prompt text inline — is a compile error with IDE autocomplete of the whole
 * library. This replaces the linter the plan originally called for: one rule, one
 * implementation, enforced by tsc.
 *
 * Partials (system-map 1c review): a prompt whose id's last segment starts with `_`
 * (`slice._design`) is included by others (`{{> slice._design }}`) and never run, so it is NOT
 * in the PromptId union — a graph cannot name it as a node's prompt. Every include in every
 * prompt must resolve (core/template.ts expandIncludes: known ids, no cycles, bounded depth),
 * or codegen fails — a broken include is caught here, not when a run pins its prompts.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { expandIncludes, isPartialId, splitFrontMatter } from "../core/template";

const ROOT = dirname(dirname(new URL(import.meta.url).pathname));
const PROMPTS = join(ROOT, "prompts");
const OUT = join(ROOT, "core", "prompt-ids.ts");

const all = readdirSync(PROMPTS)
  .filter((f) => f.endsWith(".md"))
  .map((f) => {
    const raw = readFileSync(join(PROMPTS, f), "utf8");
    const m = raw.match(/^---\n[\s\S]*?^id:\s*(\S+)\s*$[\s\S]*?\n---\n/m);
    if (!m || m[1] === undefined) throw new Error(`${f}: missing id in front-matter`);
    const fromName = f.replace(/\.md$/, "");
    if (m[1] !== fromName) throw new Error(`${f}: front-matter id "${m[1]}" != filename "${fromName}"`);
    return m[1];
  })
  .sort();

const bodyOf = (id: string) => {
  if (!all.includes(id)) throw new Error(`no prompts/${id}.md`);
  return splitFrontMatter(readFileSync(join(PROMPTS, `${id}.md`), "utf8")).body;
};
for (const id of all) {
  try {
    expandIncludes(bodyOf(id), bodyOf, [id]);
  } catch (err) {
    console.error(`prompts/${id}.md: ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  }
}
const ids = all.filter((id) => !isPartialId(id));

const banner = `// GENERATED by prompts/codegen.ts — do not edit. Regenerate: bun prompts/codegen.ts\n`;
const body =
  banner +
  `export type PromptId =\n${ids.map((id) => `  | "${id}"`).join("\n")};\n\n` +
  `export const PROMPT_IDS = [\n${ids.map((id) => `  "${id}",`).join("\n")}\n] as const;\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUT, "utf8");
  } catch {}
  if (current !== body) {
    console.error("core/prompt-ids.ts is stale — run: bun prompts/codegen.ts");
    process.exit(1);
  }
  console.log(`prompt-ids up to date (${ids.length} prompts)`);
} else {
  writeFileSync(OUT, body);
  console.log(`generated core/prompt-ids.ts with ${ids.length} prompt ids`);
}
